#!/usr/bin/env node
import { AVA_DISCORD_BOT_TOKEN } from "../src/config.mjs";
import { makeFetchJson } from "../src/discordApi.mjs";

const channelId = "1520665313631408251";
const messageId = "1533625967912685609";
const fetchJson = makeFetchJson(AVA_DISCORD_BOT_TOKEN);

const msg = await fetchJson(`/channels/${channelId}/messages/${messageId}`);
console.log("=== TARGET MESSAGE ===");
console.log(
  JSON.stringify(
    {
      id: msg.id,
      author: msg.author?.username,
      authorId: msg.author?.id,
      content: msg.content,
      timestamp: msg.timestamp,
      referenced: msg.referenced_message
        ? {
            id: msg.referenced_message.id,
            author: msg.referenced_message.author?.username,
            content: (msg.referenced_message.content || "").slice(0, 800),
          }
        : null,
    },
    null,
    2,
  ),
);

const around = await fetchJson(
  `/channels/${channelId}/messages?around=${messageId}&limit=20`,
);
console.log("\n=== NEARBY (oldest first) ===");
const sorted = [...(around || [])].sort(
  (a, b) => Number(BigInt(a.id) - BigInt(b.id)),
);
for (const m of sorted) {
  console.log("---");
  console.log(
    m.timestamp,
    `${m.author?.username} (${m.author?.id})`,
    `id=${m.id}`,
  );
  console.log((m.content || "(empty)").slice(0, 1200));
  if (m.referenced_message) {
    console.log(
      "  reply-to:",
      m.referenced_message.id,
      m.referenced_message.author?.username,
      (m.referenced_message.content || "").slice(0, 300),
    );
  }
}

// Soft-ack
for (const emoji of ["⏱️", "👀"]) {
  const enc = encodeURIComponent(emoji);
  try {
    await fetchJson(
      `/channels/${channelId}/messages/${messageId}/reactions/${enc}/@me`,
      { method: "PUT" },
    );
    console.log("reacted", emoji);
