    @media (max-width: 520px) { .kpis { grid-template-columns: repeat(2, 1fr); } }
    .kpi {
      border-top: 1px solid var(--line); padding: 0.7rem 0 0.2rem;
    }
    .kpi label {
      display: block; color: var(--muted); font-size: 0.68rem;
      text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 0.25rem;
    }
    .kpi strong { font-size: 1.2rem; font-weight: 700; font-variant-numeric: tabular-nums; }
    .kpi .hint { display: block; color: var(--muted); font-size: 0.72rem; margin-top: 0.15rem; }
    .charts {
      display: grid; grid-template-columns: 1fr 1fr; gap: 0.9rem; margin-bottom: 1.1rem;
    }
    @media (max-width: 760px) { .charts { grid-template-columns: 1fr; } }
    .chart {
      border: 1px solid var(--line); background: var(--panel);
      border-radius: 12px; padding: 0.85rem 0.85rem 0.55rem;
    }
