    }
    .panel h2 {
      font-family: Syne, sans-serif; font-size: 1rem; margin: 0 0 0.65rem; font-weight: 700;
    }
    .devices { display: grid; gap: 0.55rem; }
    .dev {
      display: grid; grid-template-columns: 1.1fr repeat(4, 0.7fr);
      gap: 0.35rem; align-items: center;
      padding: 0.55rem 0; border-bottom: 1px solid var(--line);
      font-size: 0.86rem; font-variant-numeric: tabular-nums;
    }
    @media (max-width: 640px) {
      .dev { grid-template-columns: 1fr 1fr; }
    }
    .dev .name { font-weight: 700; }
    .dev .off { color: var(--muted); font-size: 0.72rem; font-weight: 500; }
    .wx { color: var(--ink); line-height: 1.45; font-size: 0.92rem; }
    .wx .muted { color: var(--muted); }
    .hazard { color: var(--warn); margin-top: 0.35rem; }
    footer {
      margin-top: 1.5rem; color: var(--muted); font-size: 0.78rem;
      border-top: 1px solid var(--line); padding-top: 0.85rem;
    }
    footer a { color: var(--accent); }
    .empty { color: var(--muted); font-size: 0.85rem; padding: 1.5rem 0; text-align: center; }
  </style>
</head>
<body>
  <main>
    <div class="top">
      <div>
        <p class="brand">Ava Ivy</p>
        <p class="sub" id="siteLabel">HI Pacific Solar Root Server · live tracking</p>
      </div>
      <nav class="links" aria-label="Ava display tunnel">
        <a class="primary" href="https://ava.rootmc.net/" target="_blank" rel="noopener">ava.rootmc.net</a>
        <a href="https://ava.rootmc.net/solar" target="_blank" rel="noopener">Solar (tunnel)</a>
        <a href="/">Status</a>
        <a href="/solar">Solar</a>
        <a href="/health">Health</a>
        <a href="/api/solar">API</a>
      </nav>
    </div>

    <div class="kpis" id="kpis"></div>

    <div class="charts">
      <section class="chart">
        <h2>Site solar intake</h2>
        <p class="meta" id="solarMeta">watts · on-circuit only</p>
        <div id="chartSolar"></div>
        <div class="legend"><span><i style="background:var(--solar)"></i>Solar W</span></div>
      </section>
      <section class="chart">
        <h2>Battery bank</h2>
        <p class="meta">SOC % · on-circuit average</p>
        <div id="chartBank"></div>
        <div class="legend"><span><i style="background:var(--bank)"></i>Bank %</span></div>
      </section>
      <section class="chart">
        <h2>Load vs charge</h2>
        <p class="meta">site out W · solar in W</p>
        <div id="chartLoad"></div>
        <div class="legend">
          <span><i style="background:var(--load)"></i>Out (load)</span>
          <span><i style="background:var(--solar)"></i>Solar in</span>
        </div>
      </section>
      <section class="chart">
        <h2>Host CPU</h2>
        <p class="meta" id="cpuMeta">workstation sampler</p>
        <div id="chartCpu"></div>
        <div class="legend">
          <span><i style="background:var(--cpu)"></i>CPU %</span>
          <span><i style="background:#9ad0ff"></i>RAM %</span>
        </div>
      </section>
    </div>

    <div class="grid2">
      <section class="panel">
        <h2>EcoFlow devices</h2>
        <div class="devices" id="devices"></div>
      </section>
      <section class="panel">
        <h2>Weather · NWS</h2>
        <div class="wx" id="weather"></div>
        <div style="margin-top:1rem">
          <h2 style="margin-bottom:0.4rem">Array</h2>
          <div class="wx" id="array"></div>
        </div>
      </section>
    </div>

    <footer>
      Live numbers only — EcoFlow minute buckets + host-metrics + NWS.
      Tunnel display: <a href="https://ava.rootmc.net/">https://ava.rootmc.net/</a>
      · Solar: <a href="https://ava.rootmc.net/solar">/solar</a>
      · Local: <a href="http://127.0.0.1:8787/solar">:8787/solar</a>
      · Refresh <span id="age">…</span>
    </footer>
  </main>
  <script>
    const $ = (id) => document.getElementById(id);

    function esc(s) {
      return String(s ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
    }

    function fmt(n, suffix = "") {
      if (n == null || Number.isNaN(Number(n))) return "—";
      return Math.round(Number(n)) + suffix;
    }

    function fmtTime(t) {
      try {
        return new Date(t).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      } catch { return ""; }
    }

    function pathFrom(values, w, h, pad, yMax, yMin = 0) {
      const pts = values.filter((v) => v != null && Number.isFinite(Number(v)));
      if (!pts.length) return "";
      const n = values.length;
      const span = Math.max(1e-6, yMax - yMin);
      const xy = values.map((v, i) => {
        const x = pad + (n <= 1 ? 0 : (i / (n - 1)) * (w - pad * 2));
        if (v == null || !Number.isFinite(Number(v))) return null;
        const y = h - pad - ((Number(v) - yMin) / span) * (h - pad * 2);
        return [x, y];
      });
      let d = "";
      let started = false;
      for (const p of xy) {
        if (!p) { started = false; continue; }
        d += (started ? " L " : "M ") + p[0].toFixed(1) + " " + p[1].toFixed(1);
        started = true;
      }
      return d;
    }

    function areaFrom(values, w, h, pad, yMax, yMin = 0) {
      const line = pathFrom(values, w, h, pad, yMax, yMin);
      if (!line) return "";
      const n = values.length;
      const x0 = pad;
      const x1 = pad + (n <= 1 ? 0 : (w - pad * 2));
      const yBase = h - pad;
      return line + " L " + x1.toFixed(1) + " " + yBase + " L " + x0.toFixed(1) + " " + yBase + " Z";
    }

    function drawChart(el, seriesList, opts = {}) {
      const w = 560, h = 180, pad = 18;
      const all = seriesList.flatMap((s) => s.values.filter((v) => v != null));
      let yMax = opts.yMax != null ? opts.yMax : Math.max(...all, 1);
      let yMin = opts.yMin != null ? opts.yMin : 0;
      if (opts.padMax) yMax = yMax * 1.08;
      if (!all.length) {
        el.innerHTML = '<p class="empty">No samples in this window yet</p>';
        return;
      }
      const grid = [0.25, 0.5, 0.75].map((f) => {
        const y = pad + f * (h - pad * 2);
        return '<line x1="'+pad+'" x2="'+(w-pad)+'" y1="'+y+'" y2="'+y+'" stroke="rgba(232,242,234,0.08)" />';
      }).join("");
      const layers = seriesList.map((s) => {
        const stroke = s.color;
        const fill = s.fill ? areaFrom(s.values, w, h, pad, yMax, yMin) : "";
        const line = pathFrom(s.values, w, h, pad, yMax, yMin);
        return (fill
          ? '<path d="'+fill+'" fill="'+stroke+'" fill-opacity="0.18" stroke="none" />'
          : "") +
          '<path d="'+line+'" fill="none" stroke="'+stroke+'" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round" />';
      }).join("");
      const labels = opts.times || [];
      const t0 = labels[0] ? fmtTime(labels[0]) : "";
      const t1 = labels.length ? fmtTime(labels[labels.length - 1]) : "";
      el.innerHTML =
        '<svg class="plot" viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none" role="img">' +
        grid + layers +
        '<text x="'+pad+'" y="'+(h-4)+'" fill="#8aa394" font-size="10">'+esc(t0)+'</text>' +
        '<text x="'+(w-pad)+'" y="'+(h-4)+'" fill="#8aa394" font-size="10" text-anchor="end">'+esc(t1)+'</text>' +
        '<text x="'+(w-pad)+'" y="'+(pad+2)+'" fill="#8aa394" font-size="10" text-anchor="end">'+esc(Math.round(yMax))+(opts.unit||'')+'</text>' +
        '</svg>';
    }

    function render(d) {
      $("siteLabel").textContent =
        (d.site?.label || "HI Pacific Solar Root Server") + " · live tracking";
      const live = d.live || {};
      const wx = d.weather || {};
      const period = wx.period || {};
      $("kpis").innerHTML = [
        ["Bank", fmt(live.batteryPct, "%"), live.mood || ""],
        ["Solar now", fmt(live.solarW, " W"), "on-circuit"],
        ["Morning avg", live.morningAvgW != null ? "~"+fmt(live.morningAvgW, " W") : "—", live.morningNote || ""],
        ["Load out", fmt(live.outW, " W"), "site"],
        ["CPU now", fmt(live.cpu, "%"), live.hostKey || live.hostname || ""],
        ["Weather", period.temp != null ? (period.temp + (period.unit||"F")) : "—", period.short || ""],
      ].map(([k,v,h]) =>
        '<div class="kpi"><label>'+esc(k)+'</label><strong>'+esc(v)+'</strong>' +
        (h ? '<span class="hint">'+esc(h)+'</span>' : '') + '</div>'
      ).join("");

      const mins = (d.series && d.series.minutes) || [];
      const times = mins.map((m) => m.t);
      drawChart($("chartSolar"), [{ values: mins.map((m) => m.solarW), color: "#f0c14a", fill: true }], { times, padMax: true, unit: "W" });
      drawChart($("chartBank"), [{ values: mins.map((m) => m.bankSoc), color: "#3dcf7a", fill: true }], { times, yMax: 100, unit: "%" });
      drawChart($("chartLoad"), [
        { values: mins.map((m) => m.outW), color: "#7eb8ff", fill: false },
        { values: mins.map((m) => m.solarW), color: "#f0c14a", fill: false },
      ], { times, padMax: true, unit: "W" });
      drawChart($("chartCpu"), [
        { values: mins.map((m) => m.cpu), color: "#e0a84a", fill: true },
        { values: mins.map((m) => m.ram), color: "#9ad0ff", fill: false },
      ], { times, yMax: 100, unit: "%" });

      $("solarMeta").textContent =
        "watts · on-circuit · " + (d.series?.ecoSamples ?? 0) + " eco samples / " + (d.series?.hours || "?") + "h";
      $("cpuMeta").textContent =
        (live.hostname || live.hostKey || "workstation") +
        (live.cpuHour != null ? (" · 1h avg " + Math.round(live.cpuHour) + "%") : "") +
        " · " + (d.series?.cpuSamples ?? 0) + " CPU minutes";

      const devices = live.devices || [];
      $("devices").innerHTML = devices.length
        ? '<div class="dev" style="color:var(--muted);font-size:0.72rem;text-transform:uppercase;letter-spacing:0.06em"><span>Device</span><span>SOC</span><span>Solar</span><span>In</span><span>Out</span></div>' +
          devices.map((dev) =>
            '<div class="dev"><span class="name">'+esc(dev.label)+
            (dev.offCircuit ? ' <span class="off">off-circuit</span>' : '') +
            '</span><span>'+esc(fmt(dev.soc,"%"))+'</span><span>'+esc(fmt(dev.solarW,"W"))+
            '</span><span>'+esc(fmt(dev.inW,"W"))+'</span><span>'+esc(fmt(dev.outW,"W"))+'</span></div>'
          ).join("")
        : '<p class="empty">No EcoFlow snapshot yet</p>';

      let wxHtml = "";
      if (wx.ok && period.name) {
        wxHtml =
          "<div><strong>"+esc(period.name)+"</strong> · "+esc(period.temp)+esc(period.unit||"F")+
          " · "+esc(period.short||"")+(period.wind ? " · wind "+esc(period.wind) : "")+"</div>" +
          '<div class="muted">Source: '+(esc(wx.source||"NWS"))+' (local point · city private)</div>';
      } else {
        wxHtml = '<div class="muted">Weather unavailable'+(wx.detail ? " · "+esc(wx.detail) : "")+"</div>";
      }
      if (wx.alerts && wx.alerts.length) {
        wxHtml += wx.alerts.map((a) =>
          '<div class="hazard"><strong>'+esc(a.event)+'</strong>'+
          (a.severity ? " ("+esc(a.severity)+")" : "")+
          (a.headline ? " — "+esc(a.headline) : "")+"</div>"
        ).join("");
      } else if (wx.ok) {
        wxHtml += '<div class="muted" style="margin-top:0.35rem">Hazards: none active</div>';
      }
      $("weather").innerHTML = wxHtml;

      const arr = d.array || {};
      $("array").innerHTML =
        "<div><strong>"+esc(arr.panels ?? "—")+"</strong> panels / <strong>"+esc(arr.circuits ?? "—")+
        "</strong> circuits / <strong>"+esc(arr.batteries ?? "—")+"</strong> batteries</div>" +
        (arr.notes ? '<div class="muted" style="margin-top:0.35rem">'+esc(arr.notes)+"</div>" : "");

      $("age").textContent = "just now · " + (d.updatedAt || "").slice(11, 19) + "Z";
    }

    async function tick() {
      try {
        const res = await fetch("/api/solar?hours=8", { cache: "no-store" });
        const d = await res.json();
        if (d?.ok) render(d);
        else $("age").textContent = "API error";
      } catch (e) {
        $("age").textContent = "HTTP down";
      }
    }
    tick();
    setInterval(tick, 15000);
  </script>
</body>
</html>`;
}

